package frc.robot.utils.path;

import edu.wpi.first.math.geometry.Rotation2d;
import edu.wpi.first.math.geometry.Translation2d;
import edu.wpi.first.wpilibj.DriverStation;
import java.util.List;

/** Path constants generated by FRC Path Editor. */
public final class Paths {
  private Paths() {}

  public static final PathData LEFT =
      new PathData(
          List.of(
              new Translation2d(4.434355139927708, 7.815726898175398),
              new Translation2d(7.880593863220893, 7.2462213066509715),
              new Translation2d(8.596126479497867, 4.778363743378459)),
          List.of(
              new PathData.HeadingWaypoint(2, Rotation2d.fromDegrees(-90)),
              new PathData.HeadingWaypoint(1, Rotation2d.fromDegrees(-90)),
              new PathData.HeadingWaypoint(0, Rotation2d.fromDegrees(-90))),
          VelocityConstraints.defaults().withMaxVelocity(5).withMaxAcceleration(10.791),
          List.of(new PathData.ConstraintZone(1, 2, 3, 10.791)),
          List.of());

  public static final PathData RIGHT =
      new PathData(
          List.of(
              new Translation2d(4.434355139927708, 0.39427310182460307),
              new Translation2d(7.880593863220893, 0.9637786933490293),
              new Translation2d(8.596126479497867, 3.431636256621542)),
          List.of(
              new PathData.HeadingWaypoint(2, Rotation2d.fromDegrees(90)),
              new PathData.HeadingWaypoint(1, Rotation2d.fromDegrees(90)),
              new PathData.HeadingWaypoint(0, Rotation2d.fromDegrees(90))),
          VelocityConstraints.defaults().withMaxVelocity(5).withMaxAcceleration(10.791),
          List.of(new PathData.ConstraintZone(1, 2, 3, 10.791)),
          List.of());

  /**
   * Returns the path mirrored for the red alliance if needed. Call during autonomousInit() or later
   * when the alliance is known.
   */
  public static PathData forAlliance(PathData path) {
    var alliance = DriverStation.getAlliance();
    if (alliance.isPresent() && alliance.get() == DriverStation.Alliance.Red) {
      return path.mirrorForRedAlliance();
    }
    return path;
  }
}
